package ama.localdev;
import ama.worker.*;import ama.transcript.*;import ama.storage.*;import ama.minutes.ControlledMinutesDataSource;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.lang.reflect.*;import java.sql.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.core.env.*;import com.fasterxml.jackson.databind.ObjectMapper;
/** Two real publication-native-cut origins, then a saturated actual reconciliation pool. */
public final class LocalReconciliationSaturationCheck {
 static final ObjectMapper JSON=new ObjectMapper();static void check(boolean b,String m){if(!b)throw new IllegalStateException(m);}
 static final class Source extends AbstractDataSource{
  final DataSource delegate;final String mode,pub;final Path out;final CountDownLatch arrived=new CountDownLatch(1),resume=new CountDownLatch(1);final AtomicBoolean once=new AtomicBoolean();final AtomicInteger maintenance=new AtomicInteger();volatile boolean armed;
  Source(DataSource d,String m,String p,Path o){delegate=d;mode=m;pub=p;out=o;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> t,InvocationHandler h){return Proxy.newProxyInstance(t.getClassLoader(),new Class[]{t},h);}
  Connection wrap(Connection actual){var protectedLookup=new AtomicBoolean();return(Connection)proxy(actual,Connection.class,(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object r=invoke(actual,m,a);
   if(armed&&mode.equals("COEX")&&Thread.currentThread().getName().equals("ama-reconciliation")&&m.getName().equals("commit")&&protectedLookup.get()&&once.compareAndSet(false,true)){arrived.countDown();check(resume.await(23,TimeUnit.SECONDS),"Bounded actual lookup release required");}
   if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&r instanceof PreparedStatement st){var params=new HashMap<Integer,Object>();return proxy(st,PreparedStatement.class,(s,sm,sa)->{if(sm.getName().startsWith("set")&&sa!=null&&sa.length>=2&&sa[0] instanceof Integer i)params.put(i,sa[1]);Object v=invoke(st,sm,sa);
    if(armed&&sm.getName().equals("executeQuery")){
     if(Thread.currentThread().getName().equals("ama-reconciliation-poll")&&StackWalker.getInstance().walk(f->f.anyMatch(x->x.getClassName().equals("ama.transcript.JdbcPublicationLocalRecovery")&&x.getMethodName().equals("maintainLocalFailures"))))maintenance.incrementAndGet();
     if(Thread.currentThread().getName().equals("ama-reconciliation")&&sql.contains("FROM publication ")&&sql.contains("FOR UPDATE")&&StackWalker.getInstance().walk(f->f.anyMatch(x->x.getClassName().equals("ama.transcript.PublicationRecordedLookup")&&x.getMethodName().equals("captureAuthorized"))))protectedLookup.set(true);
    }
    if(armed&&mode.startsWith("CUT")&&sm.getName().equals("executeUpdate")&&sql.startsWith("INSERT INTO external_document_mapping(")&&once.compareAndSet(false,true)){check(params.containsValue(pub)&&v instanceof Number n&&n.intValue()==1&&!actual.getAutoCommit()&&org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive(),"Exact real uncommitted mapping INSERT required");Files.writeString(out.resolve(mode+"-cut.json"),JSON.writeValueAsString(Map.of("actualInsertRows",1,"publicationId",pub,"physicalTransactionActive",true,"nativeExit",86,"onlyExternalWorkerModuleStartedForFixture",true)));Runtime.getRuntime().halt(86);}
    return v;});}return r;});}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 static <T>T field(Object o,String name,Class<T> t)throws Exception{var f=o.getClass().getDeclaredField(name);f.setAccessible(true);return t.cast(f.get(o));}
 static String state(JdbcTemplate j,String id){return j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,id);}
 static List<Map<String,Object>> operations(JdbcTemplate j,List<String> ids){return j.queryForList("SELECT o.id,o.reconcile_owner,o.reconcile_epoch,e.id execution_id,e.task_id FROM external_operation o JOIN external_execution e ON e.operation_id=o.id WHERE e.task_id IN (?,?) ORDER BY e.task_id",ids.get(0),ids.get(1));}
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==4,"Explicit owned saturation qualification required");Path file=Path.of(args[0]).toRealPath(),out=Path.of(args[2]).toRealPath();String mode=args[3];check(Set.of("CUT0","CUT1","INSPECT","COEX").contains(mode)&&file.getParent().endsWith(Path.of(".tools/local-app"))&&out.startsWith(file.getParent().resolve("native-saturation")),"Exact owned scope required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Owned DB required");var fixtures=JSON.readTree(Files.readString(Path.of(args[1])));var pubs=fixtures.get("publications");var ids=List.of(pubs.get(0).get("taskId").asText(),pubs.get(1).get("taskId").asText());String publication=mode.equals("CUT0")?pubs.get(0).get("publicationId").asText():pubs.get(1).get("publicationId").asText();var original=ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password"));var source=new Source(original,mode,publication,out);var j=new JdbcTemplate(source);j.setQueryTimeout(5);
  if(mode.equals("INSPECT")){var shots=new ArrayList<Map<String,Object>>();for(var f:pubs)shots.add(LocalNativeWorkerCrashCheck.snapshot(j,f.get("meetingId").asText(),f.get("taskId").asText(),"MAPPING"));Files.writeString(out.resolve("inspection.json"),JSON.writeValueAsString(shots));return;}
  var expected=new HashSet<>(ids);if(mode.equals("COEX")){expected.add(fixtures.get("minutes").get("taskId").asText());expected.add(fixtures.get("txt").get("taskId").asText());}check(new HashSet<>(j.queryForList("SELECT id FROM durable_task WHERE state IN ('READY','RUNNING','RECONCILING')",String.class)).equals(expected),"Only actual declared fixture tasks may be pending");if(mode.equals("CUT0"))check(ids.stream().allMatch(id->state(j,id).equals("READY")),"Two actual fresh publications required");else if(mode.equals("CUT1"))check(state(j,ids.get(0)).equals("RECONCILING")&&state(j,ids.get(1)).equals("READY"),"First actual cut retained/second fresh publication required");else check(ids.stream().allMatch(id->state(j,id).equals("RECONCILING")),"Both original native-cut tasks required");
  var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var configured=ConfiguredProcessing.read(env);var definitions=ConfiguredBackends.read(env);String owner="LOCAL_SATURATION_"+out.getFileName()+"_"+mode;var provider=new TranscriptWorkerRuntimeProvider(source,definitions,configured.read(),configured.canonical(),configured.preparation(),owner,1,ConfiguredMinutes.read(env,configured.read(),configured.index()),ConfiguredPublication.read(env,configured.read(),configured.index()));
  try(var runtime=(TranscriptWorkerRuntimeProvider.Runtime)provider.create()){
   source.armed=true;if(mode.startsWith("CUT")){field(runtime,"external",WorkerLoop.class).start();Thread.sleep(90000);throw new IllegalStateException("Native cut must occur");}
   runtime.start();try{
    check(source.arrived.await(35,TimeUnit.SECONDS),"Actual protected recorded lookup S commit must pause");var before=operations(j,ids);Files.writeString(out.resolve("saturation-entry.json"),JSON.writeValueAsString(before));check(before.stream().filter(x->owner.equals(x.get("reconcile_owner"))).count()==1,"Exactly one original reconciliation may be claimed");var waiting=before.stream().filter(x->!owner.equals(x.get("reconcile_owner"))).findFirst().orElseThrow();var active=before.stream().filter(x->owner.equals(x.get("reconcile_owner"))).findFirst().orElseThrow();String activeMeeting=pubs.get(ids.indexOf((String)active.get("task_id"))).get("meetingId").asText();LocalMinutesPreparationBoundaryCheck.physicalRootFree(original,activeMeeting);var reconciliation=field(runtime,"reconciliation",ReconciliationLoop.class);check(field(reconciliation,"slots",Semaphore.class).availablePermits()==0,"Actual capacity-one reconciliation semaphore must be exhausted");int scans=source.maintenance.get();String min=fixtures.get("minutes").get("taskId").asText(),txt=fixtures.get("txt").get("taskId").asText();long begin=System.nanoTime(),end=begin+TimeUnit.SECONDS.toNanos(20);boolean progress=false;
    do{var now=operations(j,ids);var other=now.stream().filter(x->x.get("task_id").equals(waiting.get("task_id"))).findFirst().orElseThrow();check(other.equals(waiting),"Second original operation remains unclaimed while pool is full");if(state(j,min).equals("SUCCEEDED")&&state(j,txt).equals("SUCCEEDED")&&source.maintenance.get()>=scans+2){progress=true;break;}Thread.sleep(100);}while(System.nanoTime()<end);check(progress,"Real maintenance scans and ordinary minutes/TXT must progress under actual reconciliation saturation");var beforeTraffic=field(runtime,"knowledgeClient",ControlledKnowledgeClient.class).traffic();check(beforeTraffic.get("getWriteAttempts")==0&&beforeTraffic.get("postWriteAttempts")==0,"Paused S must precede provider lookup");source.armed=false;source.resume.countDown();long finish=System.nanoTime()+TimeUnit.SECONDS.toNanos(80);while(System.nanoTime()<finish&&!ids.stream().allMatch(id->state(j,id).equals("SUCCEEDED")))Thread.sleep(200);check(ids.stream().allMatch(id->state(j,id).equals("SUCCEEDED")),"Both original publications must recover");var traffic=field(runtime,"knowledgeClient",ControlledKnowledgeClient.class).traffic();check(traffic.get("getWriteAttempts")==2&&traffic.get("postWriteAttempts")==0,"Two actual GET and zero POST required");check(j.queryForObject("SELECT COUNT(*) FROM external_execution WHERE task_id=?",Long.class,min)==1&&j.queryForObject("SELECT COUNT(*) FROM generation_candidate WHERE task_id=?",Long.class,min)==1,"Ordinary generation has one execution/candidate");var report=Map.of("pass",true,"reconciliationCapacity",1,"actualSaturation",true,"secondOriginalStayedUnclaimed",true,"physicalLookupRootFree",true,"additionalActualMaintenanceQueries",source.maintenance.get()-scans,"ordinaryMinutesAndTxtSucceededWhileOccupied",true,"pauseMillis",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-begin),"knowledgeTraffic",traffic,"originalPublicationTasks",ids);Files.writeString(out.resolve("report.json"),JSON.writeValueAsString(report));System.out.println(JSON.writeValueAsString(report));
   }finally{source.armed=false;source.resume.countDown();}
  }
 }
}
